from pathlib import Path
from docx import Document
from docx.shared import Inches, Pt, RGBColor
from docx.oxml import OxmlElement
from docx.oxml.ns import qn

out = Path(__file__).parent / 'NeuroPathways Deployment Guide.docx'
d = Document()
s = d.sections[0]
s.top_margin = s.bottom_margin = Inches(.7)
s.left_margin = s.right_margin = Inches(.8)
for name in ['Normal', 'Title', 'Subtitle', 'Heading 1', 'Heading 2']:
    st=d.styles[name]; st.font.name='Calibri'; st.font.color.rgb=RGBColor(0,0,0)
d.styles['Normal'].font.size=Pt(11)
d.styles['Normal'].paragraph_format.space_after=Pt(7)
d.styles['Title'].font.size=Pt(27)
d.styles['Heading 1'].font.size=Pt(17)
d.styles['Heading 2'].font.size=Pt(13)
for style in d.styles:
    for border in list(style.element.iter(qn('w:pBdr'))):
        border.getparent().remove(border)

def p(t): d.add_paragraph(t)
def h(t): d.add_heading(t,1)
def code(t):
    a=d.add_paragraph(); a.paragraph_format.space_after=Pt(9)
    r=a.add_run(t); r.font.name='Consolas'; r.font.size=Pt(9)
def bullet(t): d.add_paragraph(t,style='List Bullet')
def page(): d.add_page_break()

d.add_heading('NeuroPathways Deployment Guide',0)
p('Operator instructions for GitHub Actions, Hostinger, Render and Neon')
p('Updated 25 October 2026 • Repository saanvirnaik/neuropathways')
p('Use this guide to deploy a reviewed Git commit to staging, verify the portal, and recover from a failed release. GitHub Actions builds and tests the application, updates the Render API, and uploads the frontend to Hostinger. Operators do not need database credentials or a local Java installation for the GitHub workflow.')
h('Current destinations')
bullet('Frontend staging: https://indigo-jackal-371617.hostingersite.com')
bullet('Backend staging: https://neuropathways-api-staging.onrender.com')
bullet('GitHub repository: https://github.com/saanvirnaik/neuropathways')
bullet('Render service: neuropathways-api-staging in My Workspace')
bullet('Neon project: NeuroPathways; staging branch br-still-smoke-b5tdj0nd')
p('Staging deployment was verified through GitHub Actions run 40162424722. The frontend, backend and verification receipt matched commit 8cc9bb6c32ae756ec6de1ce1c80d2d5e76b0afdc; the 15-question assessment and browser login succeeded.')
p('Production is deferred by the owner and is not configured. Do not treat the temporary staging address as the production launch. The existing AI Builder site at neuropathways.neurohearts.org requires a separate, planned domain cutover.')
h('Before your first deployment')
p('Ask the repository owner for access to the private repository and permission to run its Actions workflows. Install Git, GitHub CLI from https://cli.github.com, and PowerShell 7.4 or later from https://github.com/PowerShell/PowerShell. The Windows PowerShell application supplied with Windows is not sufficient.')
code('gh auth login\ngit clone https://github.com/saanvirnaik/neuropathways.git\ncd neuropathways\ngh auth status\npwsh --version')
p('Authenticate with your own authorized GitHub account. The repository already contains the deployment workflow; configuration and secrets are stored in the selected GitHub environment.')
page()
h('Deploy staging with one command')
p('Open a terminal in your repository checkout. Update your clean main branch before starting. If you have local edits, commit or preserve them before switching branches.')
code('git switch main\ngit pull --ff-only\npwsh -File scripts/Deploy-FromGitHub.ps1 -Environment Staging')
p('The command prints the unique GitHub Actions run URL and waits for that run to finish. A nonzero exit code means the workflow failed. To queue a run and return immediately, append -NoWait and monitor the printed URL.')
p('For a reviewed release, supply its full 40-character commit SHA. Replace FULL_COMMIT_SHA below with the actual value from git rev-parse HEAD or the GitHub commit page.')
code('pwsh -File scripts/Deploy-FromGitHub.ps1 `\n  -Environment Staging -Commit FULL_COMMIT_SHA')
h('What the workflow does')
bullet('Checks the SSH server key against the fingerprint verified in Hostinger hPanel, then uses the dedicated deployment key.')
bullet('Runs application tests with a disposable PostgreSQL database and builds the frontend from the selected commit.')
bullet('Deploys the exact backend commit to Render and waits for health and version checks.')
bullet('Uploads frontend assets into a versioned release directory and activates its index file. Older release assets remain available for open browser tabs.')
bullet('Checks frontend routes, authentication protection and CORS, then runs a synthetic staging learner assessment and writes a verification receipt.')
p('Render automatic deployment must stay disabled so a second deployment cannot race the workflow. GitHub serializes deployments for each environment; the Hostinger release helper also uses a deployment lock.')
h('Run from the GitHub website')
p('Open the repository, select Actions, then Deploy NeuroPathways and Run workflow. Choose main, environment Staging and operation Deploy. Leave commit blank to use the selected branch, or enter the full reviewed SHA. Leave rollback blank. Open the new run and check its final result.')
page()
h('Verify a release')
p('A successful job is required before announcing the release. Open its deployment-report artifact and retain the release ID, commit and Render deployment ID in your release record.')
bullet('Open the staging portal. Register a clearly synthetic test user, finish the assessment and confirm that a results page appears.')
bullet('Read /version.json at the frontend URL and /api/version at the backend URL. Their commit values must match the intended commit.')
bullet('Read /actuator/health at the backend URL and confirm status UP.')
bullet('For production promotion, staging must also expose /verification.json with the same commit and frontend release ID.')
p('The staging Render instance is free and may sleep when idle. Its first request can take several minutes. The deployment script allows up to six minutes for backend health and identity checks; inspect Render logs if it still fails.')
h('One time Hostinger setup')
p('This section is for administrators. Everyday operators should use Deploy. The Staging GitHub environment needs secrets HOSTINGER_SSH_KEY and RENDER_API_KEY, plus variable DEPLOY_CONFIG_JSON. Never commit private keys, API keys, database passwords or the generated environments.local.json file.')
p('The tracked deploy/environments.staging.json records nonsecret staging destinations. The JSON environment variable must supply frontendUrl, backendUrl, renderServiceId, sshHost, sshPort, sshUser, documentRoot and sshHostFingerprint. Verify the ED25519 fingerprint in hPanel before setting it.')
code('pwsh -File scripts/Deploy-FromGitHub.ps1 `\n  -Environment Staging -Operation CheckConnection')
p('The existing staging site has already been adopted and backed up successfully. The following command is retained for setup reference; everyday releases use Deploy.')
p('For the existing initial manual staging upload only, run AdoptStaging once after connectivity succeeds. It verifies the original version marker and archives the site outside public_html before enabling managed releases. It leaves the active site intact.')
code('pwsh -File scripts/Deploy-FromGitHub.ps1 `\n  -Environment Staging -Operation AdoptStaging')
p('Initialize is for an approved empty document root. It refuses a nonempty website. Never empty an existing website simply to satisfy initialization. If adoption reports partial state, inspect the backup and state directory before retrying.')
page()
h('Recover from a failed deployment')
p('Open the failed Actions run and identify the first failed step. Read its deployment-report artifact and the Render deployment events. Do not repeatedly retry while an earlier deployment is active.')
p('For a previous managed release, obtain its full release ID from a successful deployment report. It consists of a 40-character commit SHA, a hyphen, and a 12-character configuration hash. Use that exact identifier, not just the commit.')
code('pwsh -File scripts/Deploy-FromGitHub.ps1 `\n  -Environment Staging -Operation Rollback `\n  -Rollback PREVIOUS_RELEASE_ID')
p('Rollback relies on a retained Render deployment and the corresponding Hostinger assets. It does not reverse Flyway database migrations. A database change must remain compatible with the older application, or a separate database recovery plan is required.')
p('The original File Manager upload is not a managed release. Its adoption backup is initial-file-manager-backup.tar.gz in the sibling .neuropathways-deploy directory. Restoring that first upload requires administrator inspection and a matching backend version; the rollback command cannot select it.')
h('Troubleshooting')
bullet('Permission denied publickey: verify the GitHub secret contains the complete private key matching the hPanel public key. An unattended workflow cannot prompt for a passphrase. Preserve the protected original and prepare an approved CI copy securely.')
bullet('Fingerprint mismatch: stop and compare the server fingerprint in hPanel. Never disable host verification to make the workflow pass.')
bullet('SSH timeout: check that SSH is active, the endpoint and port are correct, and the GitHub runner can connect. Local network failure does not prove runner failure.')
bullet('Missing configuration: check the exact GitHub environment name and its DEPLOY_CONFIG_JSON variable and two secret names.')
bullet('Backend failure: inspect Render logs for build errors, missing environment variables, database connectivity and migration failures.')
bullet('Wrong frontend release or stale page: compare version.json, inspect caching and confirm the expected document root. Avoid editing compiled files by hand.')
bullet('Deployment lock exists: first confirm no workflow or Render deployment still owns it. An administrator must inspect the recorded owner before any manual lock cleanup.')
page()
h('Prepare production')
p('Production needs separate provisioned destinations and credentials before the Production command can work. The smallest paid Render compute option observed in the dashboard is $7 per month for 0.5 CPU and 512 MB RAM; obtain approval for recurring charges and confirm current pricing before provisioning.')
bullet('Create a separate Render production service and connect the intended Neon production database. Store database credentials only in that service. Set a separate JWT secret, the exact production CORS origin, production Spring profile, and /actuator/health as its health check.')
bullet('Disable Render automatic deployment. Confirm the GitHub repository and Docker build paths match staging.')
bullet('Prepare a separate Hostinger document root, preserve the existing site and DNS settings, and plan the custom-domain cutover and HTTPS verification.')
bullet('Create GitHub environment Production with its approved secrets and complete configuration. Include the Staging configuration so the promotion gate can verify its receipt.')
bullet('Deploy and validate the chosen commit in staging first. Promote that exact SHA only after the complete learner flow succeeds.')
code('pwsh -File scripts/Deploy-FromGitHub.ps1 `\n  -Environment Production -Commit FULL_COMMIT_SHA')
p('After promotion, verify production routes, health, version and a suitable smoke test. Confirm DNS and HTTPS independently. Record the release and a compatible rollback target.')
h('Repeat deployments and scheduling')
p('Use the same one-command script for subsequent releases. It runs on GitHub infrastructure, so your laptop only needs to dispatch and watch the run. A desktop scheduled task can invoke the command, but depends on that machine being awake and authenticated.')
p('No recurring schedule is enabled. Agree on frequency, timezone, target environment and source commit policy before adding unattended execution. Prefer explicit reviewed production promotions. A GitHub schedule needs explicit defaults because workflow_dispatch inputs are absent on scheduled events; do not merely add a cron line to the current workflow.')
h('Access and maintenance')
p('Hostinger SSH access is account-wide, so limit repository write access and protect deployment credentials. Rotate the key by registering the approved replacement public key, updating its GitHub secret, verifying connectivity, and then retiring the old key. Keep secrets out of logs and Word documents. Review database recovery, retained releases and provider quotas periodically.')
p('Reference files in the repository: README.md; scripts/Deploy-FromGitHub.ps1; scripts/Deploy-NeuroPathways.ps1; scripts/Prepare-HostingerConnection.ps1; deploy/hostinger-release.sh; .github/workflows/deploy.yml.')
d.core_properties.title='NeuroPathways Deployment Guide'
d.core_properties.subject='Deployment and recovery operator instructions'
d.core_properties.author='NeuroPathways'
d.save(out)
print(out)
